detector_raw:
{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — to maximize total profit (revenue minus raw material cost and processing cost), or to maximize total revenue, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any demand limits or minimum production requirements for each product, or can the factory produce and sell any quantity as long as equipment hours are not exceeded?"
  ],
  "rationale": "The response asks a single clarification question regarding production and demand constraints, presented as a single choice between having limits or having no limits."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For a product that can be processed on multiple equipment types (e.g., Product I on A1 or A2 for stage A), is the processing time per piece the same regardless of which equipment is used, or does it differ by equipment type?"
  ],
  "rationale": "The response asks a single clarification question regarding whether processing times vary by equipment type."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For a single piece of product, does the processing time on stage A equipment plus the processing time on stage B equipment equal the total time shown in the table, or are the stage A and stage B times separate values that I need to know individually?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific interpretation of the data structure (whether times are additive or separate)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Could you provide the individual stage A and stage B processing times (in hours per piece) for each product on each equipment type it can use?"
  ],
  "rationale": "The response asks for a single set of data (processing times for specific stages, products, and equipment), which constitutes one clarification request."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the processing cost per machine hour (e.g., 0.05 yuan/hour for A1) applied to the actual machine hours consumed by each product on that equipment, so that the total processing cost for a product on a given equipment equals the processing time per piece times the cost per hour times the number of pieces?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of a specific cost calculation formula. Although it includes an example and a detailed formula, it seeks a single yes/no confirmation regarding the application method, making it one atomic question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any constraint that the number of pieces of a product processed on stage A must equal the number processed on stage B (i.e., every piece that goes through stage A must also go through stage B, with no loss or work-in-progress)?"
  ],
  "rationale": "The response contains a single clarification question asking about a specific flow constraint between two stages. The parenthetical text explains the meaning of the question rather than asking a separate one."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the production quantities for each product required to be whole numbers (integer), or can they be fractional?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific constraint on variable types (integer vs. fractional)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For the effective machine hours on each equipment type (e.g., 6000 hours for A1), is this a hard upper limit that cannot be exceeded, or is there any flexibility or overtime option?"
  ],
  "rationale": "The response asks a single clarification question regarding whether the machine hours are a hard limit or if flexibility exists."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any minimum production requirement for each product, or can the production quantity of any product be zero?"
  ],
  "rationale": "The response asks a single clarification question regarding minimum production constraints, presented as a binary choice."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For Product I, which can be processed on A1 or A2 for stage A and on B1, B2, or B3 for stage B, is there any restriction that a piece must use the same \"route\" (e.g., if it uses A1 for stage A, it must use a specific B equipment for stage B), or can any A equipment be freely combined with any B equipment for the same product?"
  ],
  "rationale": "The response contains a single clarification question asking whether there are routing restrictions or if equipment can be freely combined. Although it presents two options (restricted vs. free), it asks for a single policy decision regarding the combination rules."
}

{
  "action": "question",
